1	/**
2	 * The MHPCO price list: the office's catalogue of what it will insure and what
3	 * each kind of thing costs. It answers the questions of item *kind* -- is this a
4	 * main item or a component, what is its tariff row -- and nothing about
5	 * underwriting policy or settlement. A new item type revises this table alone.
6	 */
7	
8	export interface Item {
9	  type: string;
10	  material?: string;
11	  enchantment?: number;
12	  cursed?: boolean;
13	}
14	
15	/**
16	 * The price list prices each main item type by its own tariff row, but prices
17	 * every component by one rule: 25 G per component, whatever its kind.
18	 */
19	const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
20	  sword: 100,
21	  amulet: 60,
22	  staff: 80,
23	  potion: 40,
24	};
25	const MAIN_ITEM_INSURANCE_VALUE: Record<string, number> = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	};
31	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
32	const COMPONENT_INSURANCE_VALUE = 250;
33	
34	export const COMPONENT_BASE_PREMIUM = 25;
35	
36	export function isComponent(type: string): boolean {
37	  return COMPONENT_TYPES.has(type);
38	}
39	
40	/**
41	 * The MHPCO insures nothing that is absent from its price list, so an unlisted
42	 * type is refused rather than priced. This is one underwriting decision, not one
43	 * per column: whichever figure is being looked up, a type without a tariff row is
44	 * a type the office does not insure. Every column reads its row through here so
45	 * that the refusal -- and one day the shape the CLI must report it as -- is
46	 * revised in a single place.
47	 */
48	function listedRow(table: Record<string, number>, type: string): number {
49	  const figure = table[type];
50	  if (figure === undefined) {
51	    throw new Error(`The MHPCO does not insure items of type "${type}"`);
52	  }
53	  return figure;
54	}
55	
56	/**
57	 * The tariff row a main item is priced from. Components have no row of their own.
58	 */
59	export function mainItemBasePremium(type: string): number {
60	  return listedRow(MAIN_ITEM_BASE_PREMIUM, type);
61	}
62	
63	/**
64	 * What the MHPCO insures an item for. Every item is insured on its own value --
65	 * the block discount is a premium concession and never lowers the insured sum.
66	 */
67	export function insuranceValue(type: string): number {
68	  if (isComponent(type)) {
69	    return COMPONENT_INSURANCE_VALUE;
70	  }
71	  return listedRow(MAIN_ITEM_INSURANCE_VALUE, type);
72	}
73	
74	/**
75	 * What a set of items insures for. The price list adds insurance values item by
76	 * item, with no group rate of any kind: 3 runes insure for 750 G even though the
77	 * same 3 runes are *premiumed* as a 60 G block. The block is a premium
78	 * concession, and this is the line that keeps it out of the insured sum.
79	 */
80	export function insuranceValueOf(items: Item[]): number {
81	  return items.reduce((total, item) => total + insuranceValue(item.type), 0);
82	}
